import json
import re

from lfx.custom import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.message import Message

SENT_SPLIT = re.compile(r"(?<=[.!?])\s+")
CLAUSE_SPLIT = re.compile(r"[,.;!?]|\b(?:tetapi|tapi|namun)\b", re.I)
NEGATION_CUE = re.compile(r"\b(?:tidak|tak|tanpa|bukan)\b", re.I)
PAIN_CUE = re.compile(r"\b(?:nyeri|sakit|pegal|perih|terbakar|seperti\s+ditekan|dipijit|remas)\b", re.I)
SEVERITY_CUE = re.compile(r"\b(?:berat|parah|hebat|sulit|tak\s+kuasa|tidak\s+kuasa)\b", re.I)
MILDNESS_CUE = re.compile(r"\b(?:ringan|sedikit|agak)\b", re.I)
PREFIX_WINDOW = 30
NEAR_WINDOW = 40

# One lexicon per spec red-flag category. Phrases that BEGIN with a negation
# cue ("tidak bisa bernapas", "tak sadarkan diri", "tidak ingin hidup") are
# intrinsically dangerous statements, so the cue inside the span is part of
# the phrase, not a negation of it. External negation ("tidak ingin bunuh
# diri", "tidak mengalami nyeri dada") is checked per mention via prefix
# window. Chest pain requires a pain/pressure expression near the mention;
# bare 'sesak' requires a severity expression while cannot-breathe phrases
# are intrinsically severe. All matching runs on the real user sentence; the
# escalation reason quotes it verbatim. No input strings are special-cased.
CHEST_ANCHOR = re.compile(r"\bdada\b", re.I)
SOBS_WITH_SEVERITY = re.compile(r"\bsesak(?:\s+napas)?\b", re.I)
SOBS_INTRINSIC = re.compile(r"\bsulit\s+bernapas\b|\bt(?:i|a)k\s+bisa\s+bernapas\b|\btidak\s+bisa\s+bernapas\b", re.I)
FAINTING_ANCHOR = re.compile(r"\bpingsan\b|\b(?:hilang(?:nya)?|kehilangan)\s+kesadaran\b|\bt(?:i|a)k\s+sadarkan\s+diri\b|\btidak\s+sadarkan\s+diri\b", re.I)
BLEEDING_ANCHOR = re.compile(r"\bpendarahan\s+(?:hebat|deras)\b|\b(?:berdarah\s+banyak|banyak\s+darah)\b", re.I)
SUICIDAL_ANCHOR = re.compile(r"\bbunuh\s+diri\b|\b(?:meng)?akhiri\s+hidup\b|\bingin\s+mati\b|\bt(?:i|a)k\s+ingin\s+hidup\b|\btidak\s+ingin\s+hidup\b", re.I)


def _prefix_negated(segment, position):
    for cue in NEGATION_CUE.finditer(segment):
        if cue.end() <= position and position - cue.end() <= PREFIX_WINDOW:
            return True
    return False


def _nearest_cue(segment, position, pattern):
    best = None
    for cue in pattern.finditer(segment):
        distance = abs(cue.start() - position)
        if distance <= NEAR_WINDOW and (best is None or distance < best[0]):
            best = (distance, cue)
    return best


def is_red_flag(sentence):
    for segment in CLAUSE_SPLIT.split(sentence):
        segment = segment.strip()
        if not segment:
            continue
        for match in CHEST_ANCHOR.finditer(segment):
            pain = _nearest_cue(segment, match.start(), PAIN_CUE)
            if pain is None:
                continue
            if _prefix_negated(segment, match.start()) or _prefix_negated(segment, pain[1].start()):
                continue
            return "chest_pain"
        for match in SOBS_INTRINSIC.finditer(segment):
            if not _prefix_negated(segment, match.start()):
                return "severe_shortness_of_breath"
        for match in SOBS_WITH_SEVERITY.finditer(segment):
            if _prefix_negated(segment, match.start()):
                continue
            severity = _nearest_cue(segment, match.start(), SEVERITY_CUE)
            if severity is None:
                continue
            mildness = _nearest_cue(segment, match.start(), MILDNESS_CUE)
            if mildness is not None and mildness[0] < severity[0]:
                continue
            if _prefix_negated(segment, severity[1].start()):
                continue
            return "severe_shortness_of_breath"
        for match in FAINTING_ANCHOR.finditer(segment):
            if not _prefix_negated(segment, match.start()):
                return "fainting_or_loss_of_consciousness"
        for match in BLEEDING_ANCHOR.finditer(segment):
            if not _prefix_negated(segment, match.start()):
                return "heavy_bleeding"
        for match in SUICIDAL_ANCHOR.finditer(segment):
            if not _prefix_negated(segment, match.start()):
                return "suicidal_statements"
    return None


class SynCareRedFlagGuard(Component):
    display_name = "SynCare F5 Red-Flag Guard"
    description = (
        "Deterministic structural red-flag bypass BEFORE scope lookup, retrieval and "
        "generation. Escalation only; no autonomous emergency, medication or diagnosis advice."
    )
    inputs = [MessageTextInput(name="input_value", display_name="Raw Patient Query JSON", required=True)]
    outputs = [
        Output(name="escalate", display_name="Escalation JSON", method="emit_escalate", group_outputs=True),
        Output(name="pass", display_name="Pass-Through Query JSON", method="emit_pass", group_outputs=True),
        Output(name="error", display_name="Input Error JSON", method="emit_error", group_outputs=True),
    ]

    def _prepare(self):
        if hasattr(self, "_prepared"):
            return self._prepared
        try:
            raw = self.input_value
            source = json.loads(raw.text if isinstance(raw, Message) else str(raw))
            query = source["query"]
            if not isinstance(query, str):
                raise ValueError("query must be a string")
            sentences = [s for s in SENT_SPLIT.split(query.strip()) if s]
            match = None
            for sentence in sentences:
                if is_red_flag(sentence):
                    match = sentence
                    break
            self._prepared = {"ok": True, "red_flag": match is not None, "reason": match or "", "pass_text": json.dumps(source, ensure_ascii=False)}
        except (ValueError, TypeError, KeyError) as exc:
            # Malformed caller input is an implementation/caller error: surfaced
            # honestly on a dedicated error branch, never masked as scope refusal.
            self._prepared = {
                "ok": False,
                "error": "invalid_query_json",
                "reason": f"{type(exc).__name__}: {exc}",
                "red_flag": False,
            }
        return self._prepared

    def _exclude(self, output):
        self.stop(output)
        self.graph.exclude_branch_conditionally(self._id, output_name=output)

    def emit_escalate(self) -> Message:
        result = self._prepare()
        if not result["ok"] or not result["red_flag"]:
            self._exclude("escalate")
            return Message(text="")
        self._exclude("pass")
        self._exclude("error")
        payload = {"action": "escalate_immediately", "reason": result["reason"]}
        return Message(text=json.dumps(payload, ensure_ascii=False))

    def emit_pass(self) -> Message:
        result = self._prepare()
        if not result["ok"] or result["red_flag"]:
            self._exclude("pass")
            return Message(text="")
        self._exclude("escalate")
        self._exclude("error")
        return Message(text=result["pass_text"])

    def emit_error(self) -> Message:
        result = self._prepare()
        if result["ok"]:
            self._exclude("error")
            return Message(text="")
        self._exclude("escalate")
        self._exclude("pass")
        return Message(text=json.dumps(result, ensure_ascii=False))

import json
import re

from langchain_google_genai import ChatGoogleGenerativeAI
from lfx.custom import Component
from lfx.io import MessageTextInput, Output, SecretStrInput
from lfx.schema.message import Message

REFUSAL = (
    "Maaf, pertanyaan itu di luar cakupan rencana Anda. "
    "Silakan tanyakan ke perawat Anda atau hubungi hotline."
)
DISCLAIMER = (
    "Jawaban demo sintetis berdasarkan rencana tindak lanjut yang telah disetujui "
    "melalui alur kerja sintetis (bukan persetujuan klinis) dan draf edukasi yang "
    "belum disetujui; bukan nasihat medis."
)
SENT_SPLIT = re.compile(r"(?<=[.!?])\s+")


def text_of(value):
    return value.text if isinstance(value, Message) else str(value)


def split_sentences(value):
    return [s for s in SENT_SPLIT.split(value.strip()) if s]


class SynCareAnswerVerifier(Component):
    display_name = "SynCare F5 Grounded Answer Verifier"
    description = (
        "Deterministic composer: reconstructs the answer verbatim from whole stored "
        "sentence units the model selected; fails closed on invalid selections."
    )
    inputs = [
        MessageTextInput(name="retrieved", display_name="Retrieved Context JSON", required=True),
        SecretStrInput(name="api_key", display_name="Google Generative AI API Key", required=True, load_from_db=True),
    ]
    outputs = [
        Output(name="answer", display_name="Grounded Answer", method="emit_answer", group_outputs=True),
        Output(name="refusal", display_name="Out-of-Scope Refusal", method="emit_refusal", group_outputs=True),
        Output(name="error", display_name="Fail-Closed Error JSON", method="emit_error", group_outputs=True),
    ]

    def _prepare(self):
        if hasattr(self, "_prepared"):
            return self._prepared
        try:
            payload = json.loads(text_of(self.retrieved))
            selection_prompt = payload["units_text"]
            llm = ChatGoogleGenerativeAI(
                model="gemini-3.5-flash-lite",
                temperature=0.2,
                google_api_key=self.api_key,
            )
            message = llm.invoke(selection_prompt)
            content = message.text if hasattr(message, "text") and not isinstance(message.text, (dict, list)) else message.content
            if isinstance(content, list):
                content = "".join(
                    part if isinstance(part, str)
                    else part.get("text", "") if isinstance(part, dict)
                    else str(part)
                    for part in content
                )
            raw = str(content)
            result = self._validate_selection(text_of(self.retrieved), raw)
            self._prepared = result
        except (ValueError, TypeError, KeyError) as exc:
            self._prepared = {
                "kind": "error",
                "error": "invalid_generated_selection",
                "reason": f"{type(exc).__name__}: {exc}",
                "disclaimer": "Synthetic demo only; invalid model selection rejected, not clinically validated.",
            }
        return self._prepared

    def _validate_selection(self, retrieved_json, raw):
        """Pure: validates a raw model selection against the retrieved payload; no SDK/network."""
        payload = json.loads(retrieved_json)
        units = {}
        for chunk in payload["retrieved"]:
            label = (
                "rencana_disetujui_workflow_sintetis" if chunk["approved"] else "draf_edukasi_tidak_disetujui"
            )
            for number, sentence in enumerate(chunk["sentences"], start=1):
                units[f"{chunk['chunk_id']}#{number}"] = (sentence, label, chunk["chunk_id"])
        if not units:
            raise ValueError("No retrieved units available")
        raw = raw.strip()
        fence = re.fullmatch(r"```(?:json)?\s*(.*?)\s*```", raw, re.S | re.I)
        selection = json.loads(fence.group(1) if fence else raw)
        if not isinstance(selection, dict) or set(selection) != {"scope", "selected_ids"}:
            raise ValueError("Selection must contain exactly scope and selected_ids")
        if selection["scope"] not in ("in_scope", "out_of_scope"):
            raise ValueError("scope must be in_scope or out_of_scope")
        selected = selection["selected_ids"]
        if not isinstance(selected, list) or any(not isinstance(v, str) for v in selected):
            raise ValueError("selected_ids must be an array of strings")
        if selection["scope"] == "out_of_scope":
            return {"kind": "refusal"}
        if not selected:
            raise ValueError("in_scope requires at least one selected id")
        unknown = [unit_id for unit_id in selected if unit_id not in units]
        if unknown:
            raise ValueError(f"selected_ids not resolvable in retrieved context: {unknown}")
        parts = []
        cited = []
        for unit_id in selected:
            sentence, label, chunk_id = units[unit_id]
            citation = f"[{unit_id} | {label}]"
            parts.append(sentence + " " + citation)
            cited.append(citation)
        answer = DISCLAIMER + " " + " ".join(parts)
        return {
            "kind": "answer",
            "answer": answer,
            "citations": cited,
        }

    def _exclude(self, output):
        self.stop(output)
        self.graph.exclude_branch_conditionally(self._id, output_name=output)

    def emit_answer(self) -> Message:
        result = self._prepare()
        if result["kind"] != "answer":
            self._exclude("answer")
            return Message(text="")
        self._exclude("refusal")
        self._exclude("error")
        return Message(text=result["answer"])

    def emit_refusal(self) -> Message:
        result = self._prepare()
        if result["kind"] != "refusal":
            self._exclude("refusal")
            return Message(text="")
        self._exclude("answer")
        self._exclude("error")
        return Message(text=REFUSAL)

    def emit_error(self) -> Message:
        result = self._prepare()
        if result["kind"] != "error":
            self._exclude("error")
            return Message(text="")
        self._exclude("answer")
        self._exclude("refusal")
        return Message(text=json.dumps(result, ensure_ascii=False))
